from pathlib import Path
import pandas as pd, json, re
base=Path('/app/dataset')
cal=json.load(open(base/'sensors_calibration.json'))['enterprise_platform']['deployment_environments']['system_config']['farms']
registry=pd.read_csv(base/'farm_registry.csv')

def enc(path):
    b=path.read_bytes()[:4]
    if b.startswith((b'\xff\xfe', b'\xfe\xff')): return 'utf-16'
    if b.startswith(b'\xef\xbb\xbf'): return 'utf-8-sig'
    return 'utf-8'

def sep_for(path, e):
    return ';' if path.read_text(encoding=e, errors='replace').splitlines()[3].count(';') > path.read_text(encoding=e, errors='replace').splitlines()[3].count(',') else ','

def parse_num(s):
    if pd.isna(s): return float('nan')
    s=str(s).strip()
    if not s or s.upper()=='ERR': return float('nan')
    if ',' in s: s=s.replace('.','').replace(',','.')
    try: return float(s)
    except: return float('nan')

def parse_dt(x):
    x=x.astype('string').str.strip()
    out=pd.Series(pd.NaT,index=x.index,dtype='datetime64[ns]')
    m=x.str.match(r'^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$', na=False)
    out.loc[m]=pd.to_datetime(x.loc[m],format='%Y-%m-%d %H:%M:%S',errors='coerce')
    m=x.str.match(r'^\d{2}\.\d{2}\.\d{4} \d{2}:\d{2}:\d{2}$', na=False)
    out.loc[m]=pd.to_datetime(x.loc[m],format='%d.%m.%Y %H:%M:%S',errors='coerce')
    return out
for farm in registry.farm_id:
    p=base/f'production_{farm}.csv'; e=enc(p); sep=sep_for(p,e)
    df=pd.read_csv(p,encoding=e,skiprows=3,sep=sep,dtype=str).drop_duplicates()
    ts_col=[c for c in df.columns if c.strip()=='timestamp'][0]
    temp_col=[c for c in df.columns if c.strip()=='inverter_temperature_C'][0]
    vcol=cal[farm]['calibration_data']['value_column_name']
    df['ts']=parse_dt(df[ts_col]); df['rec']=df[vcol].map(parse_num); df['temp']=df[temp_col].map(parse_num); df['true']=df['rec']-cal[farm]['calibration_data']['calibration_offset']
    ext=df[(df['true']>100000) & (df['ts']>=pd.Timestamp('2024-03-15')) & (df['ts']<pd.Timestamp('2024-03-16'))]
    if len(ext):
        print('\n', farm, 'extreme count', len(ext), 'vcol',repr(vcol),'type/unit',cal[farm]['sensor_info'])
        print(ext[[ts_col,temp_col,vcol,'ts','temp','rec','true']].to_string(index=False, max_rows=10))
